//! Icon geometry for the Slint prototype.
//!
//! Generated by scripts/gen-icons.py from @lucide/svelte, the icon set the
//! shipping app uses. Each constant is SVG path data in a 24x24 viewbox,
//! meant for a Path element with a 2px round stroke (see VectorIcon in
//! theme.slint). Do not edit by hand.

pub fn commands(name: &str) -> &'static str {
    match name {
        "home" => HOME,
        "wifi" => WIFI,
        "bluetooth" => BLUETOOTH,
        "share" => SHARE,
        "monitor" => MONITOR,
        "volume" => VOLUME,
        "battery" => BATTERY,
        "mouse" => MOUSE,
        "keyboard" => KEYBOARD,
        "printer" => PRINTER,
        "palette" => PALETTE,
        "window" => WINDOW,
        "lock" => LOCK,
        "bell" => BELL,
        "grid" => GRID,
        "package" => PACKAGE,
        "power" => POWER,
        "download" => DOWNLOAD,
        "history" => HISTORY,
        "drive" => DRIVE,
        "memory" => MEMORY,
        "shield" => SHIELD,
        "users" => USERS,
        "globe" => GLOBE,
        "a11y" => A11Y,
        "info" => INFO,
        "search" => SEARCH,
        "moon" => MOON,
        "zap" => ZAP,
        "plane" => PLANE,
        _ => "",
    }
}

